                } else {
                    Ok(ast::Expression::Literal(ast::Literal::Integer(s.parse().unwrap())))
                }
            }
            Token::String(s) => Ok(ast::Expression::Literal(ast::Literal::String(s))),
            Token::Minus => {
                let expr = self.parse_expression_at(PrefixOperator::Minus.precedence())?;
                Ok(ast::Expression::Operator(ast::Operator::Negate(expr.into())))
            }
            Token::Plus => {
                let expr = self.parse_expression_at(PrefixOperator::Plus.precedence())?;
                Ok(ast::Expression::Operator(ast::Operator::Identity(expr.into())))
            }
            Token::OpenParen => {
                let expr = self.parse_expression()?;
                self.expect(ast::Token::CloseParen)?;
                Ok(expr)
            }
            Token::Keyword(Keyword::Exists) => {
                self.expect(ast::Token::OpenParen)?;
                let stmt = self.parse_statement()?;
                self.expect(ast::Token::CloseParen)?;
                // EXISTS is handled by the planner, not the parser
                Ok(ast::Expression::Function("EXISTS".to_string(), vec![ast::Expression::All]))
            }
