/// Operator precedence.
type Precedence = u8;

/// Operator associativity.
enum Associativity {
    Left,
    Right,
}

impl Add<Associativity> for Precedence {
    type Output = Self;

    fn add(self, rhs: Associativity) -> Self {
        match rhs {
            Associativity::Left => self + 1,
            Associativity::Right => self,
        }
    }
}

/// Prefix operators.
enum PrefixOperator {
    Minus, // -a
    Not,   // NOT a
    Plus,  // +a
}

impl PrefixOperator {
    /// The operator precedence.
    fn precedence(&self) -> Precedence {
        match self {
            Self::Minus | Self::Plus => 10,
            Self::Not => 3,
        }
    }

    // The operator associativity. Prefix operators are right-associative by
    // definition.
    fn associativity(&self) -> Associativity {
        Associativity::Right
    }

    /// Builds an AST expression for the operator.
    fn into_expression(self, rhs: ast::Expression) -> ast::Expression {
        match self {
            Self::Minus => ast::Expression::Operator(ast::Operator::Negate(rhs.into())),
            Self::Not => ast::Expression::Operator(ast::Operator::Not(rhs.into())),
            Self::Plus => ast::Expression::Operator(ast::Operator::Identity(rhs.into())),
        }
    }
}

/// Infix operators.
enum InfixOperator {
    Add,                // a + b
    And,                // a AND b
    Divide,             // a / b
    Equal,              // a = b
    Exponentiate,       // a ^ b
    GreaterThan,        // a > b
    GreaterThanOrEqual, // a >= b
    LessThan,           // a < b
    LessThanOrEqual,    // a <= b
    Like,               // a LIKE b
    Multiply,           // a * b
    NotEqual,           // a != b
    Or,                 // a OR b
    Remainder,          // a % b
    Subtract,           // a - b
}

impl InfixOperator {
    /// The operator precedence.
    fn precedence(&self) -> Precedence {
        match self {
            Self::Or => 1,
            Self::And => 2,
            Self::Equal | Self::NotEqual | Self::Like => 4,
            Self::LessThan | Self::LessThanOrEqual | Self::GreaterThan | Self::GreaterThanOrEqual => 5,
            Self::Add | Self::Subtract => 6,
            Self::Multiply | Self::Divide | Self::Remainder => 7,
            Self::Exponentiate => 8,
        }
    }

    /// The operator associativity.
    fn associativity(&self) -> Associativity {
        Associativity::Left
    }

    /// Builds an AST expression for the infix operator.
    fn into_expression(self, lhs: ast::Expression, rhs: ast::Expression) -> ast::Expression {
        match self {
            Self::Add => ast::Expression::Operator(ast::Operator::Add(lhs.into(), rhs.into())),
            Self::And => ast::Expression::Operator(ast::Operator::And(lhs.into(), rhs.into())),
            Self::Divide => ast::Expression::Operator(ast::Operator::Divide(lhs.into(), rhs.into())),
            Self::Equal => ast::Expression::Operator(ast::Operator::Equal(lhs.into(), rhs.into())),
            Self::Exponentiate => ast::Expression::Operator(ast::Operator::Exponentiate(lhs.into(), rhs.into())),
            Self::GreaterThan => ast::Expression::Operator(ast::Operator::GreaterThan(lhs.into(), rhs.into())),
            Self::GreaterThanOrEqual => ast::Expression::Operator(ast::Operator::GreaterThanOrEqual(lhs.into(), rhs.into())),
            Self::LessThan => ast::Expression::Operator(ast::Operator::LessThan(lhs.into(), rhs.into())),
            Self::LessThanOrEqual => ast::Expression::Operator(ast::Operator::LessThanOrEqual(lhs.into(), rhs.into())),
            Self::Like => ast::Expression::Operator(ast::Operator::Like(lhs.into(), rhs.into())),
            Self::Multiply => ast::Expression::Operator(ast::Operator::Multiply(lhs.into(), rhs.into())),
            Self::NotEqual => ast::Expression::Operator(ast::Operator::NotEqual(lhs.into(), rhs.into())),
            Self::Or => ast::Expression::Operator(ast::Operator::Or(lhs.into(), rhs.into())),
            Self::Remainder => ast::Expression::Operator(ast::Operator::Remainder(lhs.into(), rhs.into())),
            Self::Subtract => ast::Expression::Operator(ast::Operator::Subtract(lhs.into(), rhs.into())),
        }
    }
}

/// Postfix operators.
enum PostfixOperator {
    Factorial,           // a!
    Is(ast::Literal),    // a IS NULL | NAN
    IsNot(ast::Literal), // a IS NOT NULL | NAN
}

impl PostfixOperator {
    // The operator precedence.
    fn precedence(&self) -> Precedence {
        9
    }

    /// Builds an AST expression for the operator.
    fn into_expression(self, lhs: ast::Expression) -> ast::Expression {
        match self {
            Self::Factorial => ast::Expression::Operator(ast::Operator::Factorial(lhs.into())),
            Self::Is(lit) => ast::Expression::Operator(ast::Operator::Is(lhs.into(), lit)),
            Self::IsNot(lit) => ast::Expression::Operator(ast::Operator::Not(ast::Operator::Is(lhs.into(), lit).into())),
        }
    }
}

